theory('Heaps (Theory Video)', 'A binary heap is a complete tree stored in an array: children of i are 2*i+1 and 2*i+2; parent is (i-1)/2. Min-heap parent<=children makes root smallest but does NOT sort the whole array. Sift-down restores order after replacing a root; sift-up after appending a leaf. Bottom-up heap construction is O(n), since most nodes sit near the leaves. PriorityQueue is a Java 8 min-heap by default. Use Collections.reverseOrder for a max-heap. Its iterator is not sorted; poll repeatedly to obtain sorted priorities. Offer/poll take O(log n), peek O(1).')
heapcode = '''    static void down(int[] a,int i,int n,boolean min){ while(true){ int best=i,l=2*i+1,r=l+1; if(l<n&&(min?a[l]<a[best]:a[l]>a[best])) best=l; if(r<n&&(min?a[r]<a[best]:a[r]>a[best])) best=r; if(best==i) return; int t=a[i]; a[i]=a[best]; a[best]=t; i=best; } }
    static int[] build(int[] a,boolean min){ for(int i=a.length/2-1;i>=0;i--) down(a,i,a.length,min); return a; }'''
for title,minheap in [('Heapify Algorithm',True),('Build heap from a given Array',True),('Convert Min Heap to Max Heap',False)]:
    add(title,heapcode+'\n    public static int[] solve(int[] a){ return build(a,%s); }'%str(minheap).lower(),'System.out.println(Arrays.toString(solve(new int[]{3,1,2})));','[1, 3, 2]' if minheap else '[3, 1, 2]',
        'Build a %s heap in place. down(a,i,n,min) is also reusable when both child subtrees are already heaps.'%('min' if minheap else 'max'),
        'Visit internal nodes bottom-up. Sift each violating node toward the smaller/larger child until its subtree obeys heap order; child subtrees were already fixed.',
        'O(n) build time, O(log n) per sift-down, O(1) auxiliary space.', 'At root 3 of [3,1,2], min-heap down swaps with 1, giving [1,3,2].', 'A heap array is not fully sorted. Calling down only at root does not fix arbitrary unsorted children.')
manualheap = '''    static class Heap { final List<Integer> a=new ArrayList<>(); final boolean min; Heap(boolean min){this.min=min;} boolean better(int x,int y){return min?x<y:x>y;} void swap(int i,int j){int t=a.get(i);a.set(i,a.get(j));a.set(j,t);} void offer(int x){a.add(x);for(int i=a.size()-1;i>0;){int p=(i-1)/2;if(!better(a.get(i),a.get(p)))break;swap(i,p);i=p;}} int peek(){if(a.isEmpty())throw new NoSuchElementException();return a.get(0);} int poll(){int ans=peek(),last=a.remove(a.size()-1);if(!a.isEmpty()){a.set(0,last);for(int i=0;;){int best=i,l=2*i+1,r=l+1;if(l<a.size()&&better(a.get(l),a.get(best)))best=l;if(r<a.size()&&better(a.get(r),a.get(best)))best=r;if(best==i)break;swap(i,best);i=best;}}return ans;} boolean isEmpty(){return a.isEmpty();} }'''
for title,small in [('Implement Min Heap',True),('Implement Max Heap',False)]:
    add(title,manualheap,'Heap h=new Heap(%s); h.offer(3); h.offer(1); h.offer(2); List<Integer> a=new ArrayList<>(); while(!h.isEmpty()) a.add(h.poll()); System.out.println(a);'%str(small).lower(),'[1, 2, 3]' if small else '[3, 2, 1]',
        'Resizable int %s heap, supporting offer,peek,poll,isEmpty. Empty peek/poll throws.'%('min' if small else 'max'),
        'Offer appends and sifts up while beating parent. Poll removes root, places last at root, then sifts down to the better child. Only one root-to-leaf path can violate order after each operation.',
        'O(log n) offer/poll, O(1) peek; O(n) stored values, O(1) auxiliary state.', 'Insert 3 then 1 then 2; root reflects the current extremum. Repeated poll emits priority order.', 'No comparator subtraction is used, so extreme int values are safe. ArrayList stores boxed integers.')
add('Check if an array represents a min heap', '''    public static boolean solve(int[] a){ for(int i=1;i<a.length;i++) if(a[(i-1)/2]>a[i]) return false; return true; }''','System.out.println(solve(new int[]{1,3,2,5}));','true',
    'Check min-heap order on a complete array representation.', 'Every nonroot node must be no smaller than its parent. This local relation along paths makes the root a global minimum.', 'O(n) time, O(1) space.', '1<=3,1<=2,3<=5, so all parent-child comparisons pass.', 'Sortedness is sufficient but not necessary for heap order. Empty/singleton arrays are heaps.')
add('Heap Sort',heapcode+'''\n    public static int[] solve(int[] a){ build(a,false); for(int end=a.length-1;end>0;end--){ int t=a[0]; a[0]=a[end]; a[end]=t; down(a,0,end,false); } return a; }''','System.out.println(Arrays.toString(solve(new int[]{4,1,3,2})));','[1, 2, 3, 4]',
    'Sort ascending in place with a max heap.', 'Swap the maximum root to the last active position, shrink the active heap, and restore root order. Settled suffix is sorted and never revisited.', 'O(n log n) time; O(1) space; not stable.', 'Heap [4,2,3,1] puts 4 last, then 3,2,1 settle in sequence.', 'Pass the active prefix length to down; including the sorted suffix would undo progress.')
topk = '''    public static int solve(int[] a,int k){ if(k<1||k>a.length) throw new IllegalArgumentException(); PriorityQueue<Integer> q=new PriorityQueue<>(); for(int x:a){ q.offer(x); if(q.size()>k) q.poll(); } return q.peek(); }'''
add('K-th Largest element in an array',topk,'System.out.println(solve(new int[]{3,2,1,5,6,4},2));','5',
    'Return ONE-based kth largest entry; duplicates count individually.', 'Retain the largest k values in a min-heap; whenever size exceeds k, discard its smallest. Heap root is the smallest of the largest k.', 'O(n log(k+1)) time; O(k) space.', 'For k=2, final retained values are 5 and 6; root is 5.', 'Validate k before peek. kth distinct largest is a different contract.', 'Sort in O(n log n); randomized quickselect has expected O(n) time but worst O(n²).')
add('Kth largest element in a stream of running integers', '''    static class KthLargest { final int k; final PriorityQueue<Integer> q=new PriorityQueue<>(); KthLargest(int k){if(k<1)throw new IllegalArgumentException();this.k=k;} OptionalInt add(int x){q.offer(x);if(q.size()>k)q.poll();return q.size()<k?OptionalInt.empty():OptionalInt.of(q.peek());} }''','KthLargest stream=new KthLargest(2); stream.add(3); stream.add(5); System.out.println(stream.add(4).getAsInt());','4',
    'Track kth largest after each inserted value; return empty until k values have arrived.', 'Maintain exactly the same largest-k min-heap invariant as batch selection; historical values below the threshold can be discarded permanently.', 'O(log k) per update, O(k) storage.', '3 then 5 retains {3,5}; 4 discards 3, leaving {4,5} and answer 4.', 'A heap with fewer than k values cannot answer kth rank; OptionalInt makes that explicit.')
add('Sort K sorted array', '''    public static int[] solve(int[] a,int k){ if(k<0) throw new IllegalArgumentException(); PriorityQueue<Integer> q=new PriorityQueue<>(); int read=0,write=0; while(read<a.length&&read<=k) q.offer(a[read++]); while(!q.isEmpty()){ a[write++]=q.poll(); if(read<a.length) q.offer(a[read++]); } return a; }''','System.out.println(Arrays.toString(solve(new int[]{3,1,2,5,4},2)));','[1, 2, 3, 4, 5]',
    'Every value is at most k positions from its final sorted location. Sort in place.', 'The next smallest value must lie in the next k+1 unread/queued candidates. Poll one, then add the next unread value.', 'O(n log(min(n,k+1)+1)) time; O(min(n,k+1)) heap space.', 'First candidates 3,1,2 emit 1; insert 5, emit 2; insert 4, then emit 3,4,5.', 'Without the k-displacement promise a small heap may produce an incorrect sort. k=0 expects already sorted input.')
add('Merge K sorted Lists',node+'''\n    public static Node solve(Node[] heads){ PriorityQueue<Node> q=new PriorityQueue<>((a,b)->Integer.compare(a.value,b.value)); for(Node h:heads) if(h!=null) q.offer(h); Node dummy=new Node(0),tail=dummy; while(!q.isEmpty()){ Node p=q.poll(),next=p.next; tail.next=p; tail=p; if(next!=null) q.offer(next); } if(tail!=dummy) tail.next=null; return dummy.next; }''','System.out.println(view(solve(new Node[]{list(1,4),list(2,5),list(3,6)})));','[1, 2, 3, 4, 5, 6]',
    'Merge k disjoint sorted next chains by relinking nodes.', 'Heap holds one front per nonempty chain. The smallest front is globally smallest among remaining entries; after taking it insert only its successor.', 'O(N log(k+1)) time; O(k) heap space.', 'Heap initially 1,2,3; polling 1 inserts 4, then polling 2 inserts 5.', 'Shared nodes or cycles violate the contract and could duplicate nodes or create loops.')
add('Replace Elements by Their Rank', '''    public static int[] solve(int[] input){ int[] sorted=input.clone(); Arrays.sort(sorted); Map<Integer,Integer> rank=new HashMap<>(); for(int x:sorted) if(!rank.containsKey(x)) rank.put(x,rank.size()+1); int[] out=new int[input.length]; for(int i=0;i<out.length;i++) out[i]=rank.get(input[i]); return out; }''','System.out.println(Arrays.toString(solve(new int[]{40,10,20,30,20})));','[4, 1, 2, 3, 2]',
    'Dense ranks start at one; equal values share rank, larger distinct values have larger rank.', 'Sort values, assign a new rank only on the first occurrence of a distinct value, then map original positions.', 'O(n log n) time; O(n) space.', 'Distinct order 10,20,30,40 gets ranks 1,2,3,4.', 'Rank is based on distinct values, not original indices. Input remains unchanged.')
add('Task Scheduler', '''    public static long solve(char[] tasks,int cooldown){ if(cooldown<0) throw new IllegalArgumentException(); int[] count=new int[26]; for(char c:tasks){ if(c<'A'||c>'Z') throw new IllegalArgumentException(); count[c-'A']++; } int max=0,ties=0; for(int f:count) max=Math.max(max,f); for(int f:count) if(f==max&&f>0) ties++; return Math.max(tasks.length,(long)(max-1)*(cooldown+1L)+ties); }''','System.out.println(solve(new char[]{\'A\',\'A\',\'A\',\'B\',\'B\',\'B\'},2));','8',
    'Unit tasks A..Z, repeated same task needs at least cooldown intervening time units. Return minimum total including idle.', 'The most frequent tasks force max-1 frames of length cooldown+1 plus the tied maximum tasks at the tail. If other tasks fill more than this lower bound, total task count dominates; arranging tasks in those frames achieves it.', 'O(n+26) time; O(26) space.', 'A B idle A B idle A B uses eight units for cooldown two.', 'Idle contributes time but not tasks. Empty input returns zero via max(total,frameBound).')
add('Hand of Straights', '''    public static boolean solve(int[] hand,int group){ if(group<=0) throw new IllegalArgumentException(); if(hand.length%group!=0) return false; TreeMap<Integer,Integer> count=new TreeMap<>(); for(int x:hand) count.put(x,count.getOrDefault(x,0)+1); while(!count.isEmpty()){ int start=count.firstKey(); for(int i=0;i<group;i++){ long value=(long)start+i; if(value>Integer.MAX_VALUE) return false; int x=(int)value; Integer f=count.get(x); if(f==null) return false; if(f==1) count.remove(x); else count.put(x,f-1); } } return true; }''','System.out.println(solve(new int[]{1,2,3,6,2,3,4,7,8},3));','true',
    'Partition all cards into groups of exactly group consecutive integer values, counting duplicates.', 'The smallest remaining card must start some group: nothing smaller remains to precede it. Remove one of each required consecutive value, repeat.', 'O(n log u) time; O(u) space.', 'Groups [1,2,3],[2,3,4],[6,7,8] consume all cards.', 'Check total divisibility first; value arithmetic uses long to reject range overflow.')
add('Minimum Cost to Connect Sticks', '''    public static long solve(int[] a){ PriorityQueue<Long> q=new PriorityQueue<>(); for(int x:a){ if(x<0) throw new IllegalArgumentException(); q.offer((long)x); } long cost=0; while(q.size()>1){ long joined=q.poll()+q.poll(); cost+=joined; q.offer(joined); } return cost; }''','System.out.println(solve(new int[]{2,4,3}));','14',
    'Joining two nonnegative stick lengths costs their sum and creates one new stick; minimize total.', 'Always merge the two shortest. The optimal merge-tree exchange argument places the two smallest leaves deepest as siblings; collapsing them reduces to the same smaller problem.', 'O(n log n) time; O(n) heap space.', '2+3=5 costs 5, then 4+5=9 costs 9, total 14.', 'Zero/singleton input costs zero. Use long for joined lengths and cost; extremely large aggregate cost may require BigInteger.')
add('Maximum Sum Combination', '''    static class Pair { int i,j; long sum; Pair(int i,int j,int[] a,int[] b){this.i=i;this.j=j;sum=(long)a[i]+b[j];} }
    public static List<Long> solve(int[] aa,int[] bb,int k){ if(k<0||(long)k>(long)aa.length*bb.length) throw new IllegalArgumentException(); int[] a=aa.clone(),b=bb.clone(); Arrays.sort(a); Arrays.sort(b); List<Long> out=new ArrayList<>(); if(k==0) return out; PriorityQueue<Pair> q=new PriorityQueue<>((x,y)->Long.compare(y.sum,x.sum)); Set<Long> seen=new HashSet<>(); int i=a.length-1,j=b.length-1; q.offer(new Pair(i,j,a,b)); seen.add(((long)i<<32)|(j&0xffffffffL)); while(out.size()<k){ Pair p=q.poll(); out.add(p.sum); for(int[] index:new int[][]{{p.i-1,p.j},{p.i,p.j-1}}) if(index[0]>=0&&index[1]>=0){ long key=((long)index[0]<<32)|(index[1]&0xffffffffL); if(seen.add(key)) q.offer(new Pair(index[0],index[1],a,b)); } } return out; }''','System.out.println(solve(new int[]{1,4,2,3},new int[]{2,5,1,6},3));','[10, 9, 9]',
    'Return the k largest pair sums a[i]+b[j], counting distinct index pairs even if sums repeat.', 'Sorted arrays form a monotone sum grid. Begin at its largest corner, pop the largest candidate and add its lower-index neighbors. The frontier contains the next possible largest values; a set prevents revisiting pairs.', 'O(n log n+m log m+k log(k+1)) time; O(n+m+k) space.', '4+6=10; its neighbors 3+6 and 4+5 both give 9.', 'Deduplicate coordinate pairs, not sums. Validate k against number of possible pairs.')
median_stream = '''    static class MedianFinder { final PriorityQueue<Integer> low=new PriorityQueue<>(Collections.reverseOrder()),high=new PriorityQueue<>(); void add(int x){ if(low.isEmpty()||x<=low.peek()) low.offer(x); else high.offer(x); if(low.size()>high.size()+1) high.offer(low.poll()); if(high.size()>low.size()) low.offer(high.poll()); } double median(){if(low.isEmpty())throw new NoSuchElementException();return low.size()>high.size()?low.peek():((long)low.peek()+high.peek())/2.0;} }'''
add('Find Median from Data Stream',median_stream,'MedianFinder m=new MedianFinder(); m.add(1); m.add(2); System.out.println(m.median()); m.add(3); System.out.println(m.median());','1.5\n2.0',
    'After each insertion return the median of all seen values; no value exists before the first insertion.', 'Max-heap low contains the smaller half; min-heap high the larger. Keep low the same size or one larger and every low value<=every high value. Middle value(s) are the roots.', 'O(log n) insertion, O(1) median; O(n) storage.', 'After 1,2 roots are 1 and 2 ->1.5; after 3 low root 2 ->2.', 'Widen before averaging roots to avoid int overflow. Heap iterators do not give sorted order.')
add('Top K Frequent Elements', '''    public static List<Integer> solve(int[] a,int k){ Map<Integer,Integer> f=new HashMap<>(); for(int x:a) f.put(x,f.getOrDefault(x,0)+1); if(k<0||k>f.size()) throw new IllegalArgumentException(); List<Integer> keys=new ArrayList<>(f.keySet()); keys.sort((x,y)->{int c=Integer.compare(f.get(y),f.get(x));return c!=0?c:Integer.compare(x,y);});return new ArrayList<>(keys.subList(0,k)); }''','System.out.println(solve(new int[]{1,1,1,2,2,3},2));','[1, 2]',
    'Return k distinct values ranked by descending frequency then ascending value.', 'Count once and sort distinct keys using the stated tie comparator. Take the first k.', 'Expected O(n+u log u) time; O(u) space.', 'Counts 1:3,2:2,3:1 give top two 1,2.', 'k<=distinct count, not input length. For large u and small k use a size-k heap in O(n+u log k), or frequency buckets.')
twitter = '''    static class Twitter {
        static class Tweet { int id; long time; Tweet(int id,long time){this.id=id;this.time=time;} }
        long clock; final Map<Integer,List<Tweet>> posts=new HashMap<>(); final Map<Integer,Set<Integer>> following=new HashMap<>();
        void postTweet(int user,int id){posts.computeIfAbsent(user,k->new ArrayList<>()).add(new Tweet(id,clock++));}
        void follow(int user,int other){following.computeIfAbsent(user,k->new HashSet<>()).add(other);}
        void unfollow(int user,int other){Set<Integer> set=following.get(user);if(set!=null)set.remove(other);}
        List<Integer> getNewsFeed(int user){Set<Integer> users=new HashSet<>(following.getOrDefault(user,Collections.emptySet()));users.add(user);PriorityQueue<Tweet> q=new PriorityQueue<>((a,b)->Long.compare(a.time,b.time));for(int u:users)for(Tweet t:posts.getOrDefault(u,Collections.emptyList())){q.offer(t);if(q.size()>10)q.poll();}List<Integer> out=new ArrayList<>();while(!q.isEmpty())out.add(q.poll().id);Collections.reverse(out);return out;}
    }'''
add('Design Twitter',twitter,'Twitter t=new Twitter(); t.postTweet(1,5); t.follow(1,2); t.postTweet(2,6); System.out.println(t.getNewsFeed(1)); t.unfollow(1,2); System.out.println(t.getNewsFeed(1));','[6, 5]\n[5]',
    'In-memory post/follow/unfollow/feed API. Feed includes own posts and followed users, newest first, limited to ten.', 'Assign a monotone timestamp per post. For a feed scan eligible histories retaining the newest ten in a min-heap, then reverse their extracted order.', 'O(1) amortized post/follow/unfollow with hash maps; O(H log 10) feed time for H eligible historical posts; O(total posts+follow edges) stored state.', 'User 1 sees own tweet 5 and followed user 2\'s newer 6; after unfollow only 5 remains.', 'Self-follow is harmless because feed users form a set. This reference prioritizes clarity; a k-way heap over each user\'s last post reduces feed work to O(followees+10 log followees).')
